product.product_source IN ('TEENY', 'FINLIFE')
OR product.target_child_id = #{memberId}
OR product.created_by_parent_id = #{memberId}

mapper.select:
SELECT * FROM T_DPT_PROD_M
WHERE id = #{id}
  AND is_active = TRUE

SELECT * FROM T_SVG_PROD_M
WHERE id = #{id}
  AND is_active = TRUE

SELECT COUNT(*) FROM T_DPT_ENROLL_M
WHERE child_id = #{childId} AND deposit_id = #{productId}
  AND status = 'PENDING'

SELECT COUNT(*) FROM T_SVG_ENROLL_M
WHERE child_id = #{childId} AND saving_id = #{productId}
  AND status = 'PENDING'

SELECT COUNT(*) FROM T_LON_ENROLL_M
WHERE child_id = #{childId} AND loan_id = #{productId}
  AND status = 'PENDING'

SELECT COUNT(*)
FROM T_SVG_PAYHIST_H
WHERE saving_enrollment_id = #{enrollmentId}
  AND installment_no = #{installmentNo}

SELECT COALESCE(SUM(paid_amount), 0)
FROM T_SVG_PAYHIST_H
WHERE saving_enrollment_id = #{enrollmentId}
  AND status IN ('PAID', 'PARTIAL')
  AND paid_at >= #{from}
  AND paid_at < #{to}

SELECT COUNT(*)
FROM T_LON_REPAYHIST_H
WHERE loan_enrollment_id = #{enrollmentId}
  AND installment_no = #{installmentNo}

SELECT COUNT(*)
FROM T_LON_REPAYHIST_H
WHERE loan_enrollment_id = #{enrollmentId}
  AND installment_no = #{installmentNo}
  AND created_at >= #{attemptDate}
  AND created_at < DATE_ADD(#{attemptDate}, INTERVAL 1 DAY)

SELECT DATE(MAX(created_at))
FROM T_LON_REPAYHIST_H
WHERE loan_enrollment_id = #{enrollmentId}
  AND installment_no = #{installmentNo}
